class Visitor
  def visit(node)
    m = dispatch[node.class]                     # cached, e.g. :visit_UnionShape
    respond_to?(m, true) ? send(m, node) : visit_default(node)
  end
  private
  def dispatch = @dispatch ||= Hash.new { |h, k| h[k] = :"visit_#{k.name.gsub('::', '_')}" }
  def visit_default(node) = raise(NotImplementedError, "no handler for #{node.class}")
end
class UnionVisitor < Visitor                      # inherit the traversal, add one case
  def visit_UnionShape(node) = [node.a, node.b].each { |child| visit(child) }
end
